  const table = (headers,rows) => `<div class="mt-4 rounded-lg border border-[#e5e2ed] bg-white overflow-x-auto"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const channelRows = list => table(['Channel','Subscribers','Views'],list.map(c=>[identity(c),esc(c.subscribers),esc(c.views)]));
  function renderPreview(type){
    if(type==='overview') return metrics([['MCN partners',atlas.organization.partnerCount],['Organization channels',atlas.organization.channelCount],['Active contracts',atlas.organization.activeContracts],['Mapped channels',atlas.organization.mappedChannels]])+`<div class="grid lg:grid-cols-[1fr_1.2fr] gap-3 mt-4"><div class="bg-white border border-[#e5e2ed] rounded-lg p-4"><h3 class="text-xs font-medium mb-3">Partner networks</h3>${atlas.partners.map(p=>`<div class="border-t border-[#e5e2ed] py-3"><p class="text-sm font-medium">${esc(p.name)}</p><p class="text-[11px] muted mt-1">${esc(p.alias)} · ${esc(p.type)}</p></div>`).join('')}</div><div class="bg-white border border-[#e5e2ed] rounded-lg p-4"><h3 class="text-xs font-medium mb-3">Channels in the network</h3>${featured.map(c=>`<div class="flex justify-between items-center py-3 gap-3">${identity(c)}<div class="text-right text-xs whitespace-nowrap">${esc(c.views)}<span class="block text-[10px] muted mt-1">views</span></div></div>`).join('')}</div></div>`;
    if(type==='mcns') return `<p class="text-sm muted mt-5">${atlas.organization.partnerCount} partner networks connected to ${esc(atlas.organization.name)}.</p>`+table(['Partner network','Type','Legal entity'],atlas.partners.map(p=>[esc(p.name),`<span class="status neutral">${esc(p.type)}</span>`,esc(p.alias)]));
    if(type==='channels') return `<div class="flex justify-between items-center gap-3 mt-5"><h3 class="text-sm font-medium">Channels across partner networks</h3><span class="text-[10px] muted">${atlas.channels.length} channels</span></div><div class="max-h-[340px] overflow-y-auto rounded-lg mt-3" tabindex="0" role="region" aria-label="Organization channel records">${channelRows(atlas.channels)}</div>`;
  }
  const processCard = (title,items,note) => `<div class="workflow-card"><h3 class="text-xl font-medium tracking-tight">${title}</h3><ul class="mt-6">${items.map(([a,b])=>`<li class="py-4 border-t border-[#e5e2ed]"><p class="text-sm font-medium">${a}</p><p class="text-xs muted mt-2 leading-relaxed">${b}</p></li>`).join('')}</ul><p class="text-[11px] muted leading-relaxed mt-5">${note}</p></div>`;
  const steps=[
    `<p class="text-xs muted mb-5">Connected channels / P2P Labs</p><div class="workflow-card"><h3 class="font-medium text-lg">Know the channels in your network.</h3>${channelRows(featured)}</div>`,
    `<p class="text-xs muted mb-5">Campaign planning</p>`+processCard('Give the partnership a clear plan.',[['Campaign identity','Define the brand, brief, products, and campaign dates.'],['Creator packages','Set deliverables and investment for your roster.'],['Saved forecast','Review launch readiness and save an estimated baseline.']],'Forecasts are estimates. A saved forecast becomes the campaign baseline at launch.'),
    `<p class="text-xs muted mb-5">Content coordination</p>`+processCard('Keep every submission connected.',[['Atlas campaign codes','Link creator submissions to the correct campaign.'],['Video submission','Reserve a pre-upload intent or attach a posted video link.'],['Verification','Review submissions before including tracked videos in monitoring.']],'Only tracked videos contribute to campaign monitoring.'),
    `<p class="text-xs muted mb-5">Channel evidence / P2P Labs</p><div class="workflow-card"><h3 class="font-medium text-lg">Start with the available evidence.</h3>${channelRows(featured)}</div>`
  ];
  const audiences={
    agency:{title:'Your campaign, in one clear view.',copy:'Move from a creator shortlist to a coordinated campaign. Keep the plan, the people, and the evidence connected in the Agency Console.',list:['Compare creators and YouTube packages','Review applicants and coordinate delivery','Monitor tracked videos against the campaign baseline'],cta:'Discuss your next campaign',href:'#',card:'Partner networks',caption:'Connected to PT Sorak Digital Media',items:atlas.partners.map(p=>[p.name,p.type])},
    creator:{title:'More clarity around your next collaboration.',copy:'Find open campaigns, put forward your rates, and follow what happens next. The Creator Portal keeps your participation and submissions in view.',list:['Browse open campaigns after signing in','Apply with your channel and proposed rates','Track decisions and submit campaign videos'],cta:'Create a creator account',href:'/register/creator',card:'Connected YouTube channels',caption:'Creators in the P2P Labs network',items:featured.map(c=>[c.name,c.subscribers+' subscribers'])},
    network:{title:'Keep your creator network connected.',copy:'Organize channels and partner networks with clear ownership, scoped access, and contracts. Build an operational home for long-term creator relationships.',list:['Manage organizations, networks, and channels','Set channel contracts and revenue splits','Give each team access to the right scope'],cta:'Become a partner network',href:'#',card:'Organization workspace',caption:atlas.organization.name,items:[['MCN partners',atlas.organization.partnerCount],['Organization channels',atlas.organization.channelCount],['Active contracts',atlas.organization.activeContracts]]}
  };
  function renderAudience(key){const a=audiences[key];return `<div><h3 class="text-[30px] leading-tight tracking-tight font-medium max-w-[400px]">${a.title}</h3><p class="mt-5 text-base muted leading-[1.75]">${a.copy}</p><ul class="space-y-3 mt-6 text-sm">${a.list.map(s=>`<li class="flex gap-3"><span class="text-[#7250ce]" aria-hidden="true">✓</span>${s}</li>`).join('')}</ul><a class="button secondary mt-7" href="${a.href}">${a.cta}<span aria-hidden="true">↗</span></a></div><div class="bg-[#f6f5f9] rounded-[20px] p-6 md:p-9"><div class="workflow-card"><div class="flex gap-3 items-center"><img src="/atlas-nexus-icon.png" width="35" height="35" alt=""><p class="text-sm font-medium">${a.card}</p></div><h4 class="text-xl font-medium tracking-tight mt-6 mb-4">${a.caption}</h4>${a.items.map(([label,value])=>`<div class="flex items-center justify-between gap-4 border-t border-[#e5e2ed] py-4"><span class="text-sm muted">${esc(label)}</span><span class="text-xs font-medium shrink-0">${esc(value)}</span></div>`).join('')}</div></div>`;}

const preview = ref('overview')
const step = ref(0)
const audience = ref('agency')
const menuOpen = ref(false)
const menuButton = ref(null)
const year = new Date().getFullYear()
const previewContent = computed(() => renderPreview(preview.value))
const audienceContent = computed(() => renderAudience(audience.value))
const channelEvidence = channelRows(featured)
const heroChannels = featured.map(c => `<div class="scene-channel"><img src="${esc(c.thumbnail)}" alt="" width="35" height="35"><div><strong>${esc(c.name)}</strong><small>${esc(c.partner)}</small></div></div>`).join('')
function tabKey(event, group, keys, active, vertical = false) {
  const index = keys.indexOf(active)
  let next
  if (event.key === (vertical ? 'ArrowDown' : 'ArrowRight')) next = (index + 1) % keys.length
  if (event.key === (vertical ? 'ArrowUp' : 'ArrowLeft')) next = (index - 1 + keys.length) % keys.length
  if (event.key === 'Home') next = 0
  if (event.key === 'End') next = keys.length - 1
  if (next === undefined) return
  event.preventDefault()
  if (group === 'preview') preview.value = keys[next]
  if (group === 'step') step.value = keys[next]
  if (group === 'audience') audience.value = keys[next]
  // Focus is restricted to the tablist that received the keyboard event.
  event.currentTarget.parentElement.querySelectorAll('[role="tab"]')[next]?.focus()
}
function closeMenu() { menuOpen.value = false }
function escapeMenu(event) {
  if (event.key === 'Escape' && menuOpen.value) {
    closeMenu()
    menuButton.value?.focus()
  }
}
function resizeMenu() { if (window.innerWidth >= 768) closeMenu() }
onMounted(() => {
  document.addEventListener('keydown', escapeMenu)
  window.addEventListener('resize', resizeMenu)
})
onBeforeUnmount(() => {
  document.removeEventListener('keydown', escapeMenu)
  window.removeEventListener('resize', resizeMenu)
})

</script>

